def participant_union(values):
    if not values:
        return None
    out=values[0]
    i=1
    while i<len(values):
        out=['participant_union',out,values[i]]
        i+=1
    return out


def condition_union(values):
    if not values:
        return ['no_condition']
    out=values[0]
    i=1
    while i<len(values):
        out=['and_condition',out,values[i]]
        i+=1
    return out


def trigger_union(values):
    clean=[]
    for value in values:
        if value not in clean:
            clean.append(value)
    if not clean:
        return None
    out=clean[0]
    i=1
    while i<len(clean):
        out=['trigger_alternative',out,clean[i]]
        i+=1
    return out


def add_statement(rows,seen,term,support):
    ids=[]
    for uid in support:
        if isinstance(uid,int) and uid not in ids:
            ids.append(uid)
    ids=sorted(ids)
    key=repr(term)+'|'+repr(ids)
    if ids and key not in seen:
        seen.add(key)
        rows.append({'term':term,'support_ids':ids})


def full_audit_ids(answer,unit_text):
    record=answer.get('complete_source_evidence')
    if not isinstance(record,dict):
        return []
    ids=record.get('unit_ids',[])
    if not isinstance(ids,list):
        return []
    out=[]
    for uid in ids:
        if isinstance(uid,int) and uid in unit_text and uid not in out:
            out.append(uid)
    return out


def source_bundle(derivatives):
    ci=['confidential_information']
    copies=['copies_of',ci]
    bundle=['information_bundle',ci,copies]
    if derivatives:
        bundle=['information_bundle',bundle,['derivative_materials_of',ci]]
    return bundle


def disclosure_exception(text):
    low=text.lower()
    values=[]
    if 'without prior written consent' in low or 'without the express written consent' in low or 'without prior written approval' in low:
        values.append(['authorization_exception',text])
    if 'except as is required in the course of service' in low or 'except as required in the course of service' in low:
        values.append(['purpose_exception',text])
    if 'except as provided herein' in low:
        values.append(['cross_reference_exception',text])
    if not values:
        return ['no_exceptions']
    out=['exception_set',values[0]]
    i=1
    while i<len(values):
        out=['add_exception',out,values[i]]
        i+=1
    return out


def nearby_text(valid,index,before,after):
    start=max(0,index-before)
    end=min(len(valid),index+after+1)
    texts=[]
    ids=[]
    i=start
    while i<end:
        ids.append(valid[i][0])
        texts.append(valid[i][1])
        i+=1
    return ' '.join(texts),ids


